begin;

insert into public.quiz_bank (title, description, group_id, quiz_type, difficulty, category, questions, scheduled_date, status, verified_at, verification_notes)
values
  ('ITZY: From Debut to Born to Be', 'How well do you know ITZY? Ten questions on the JYP girl group''s debut, its name, its early singles and its EPs up to Born to Be.', 17, 'multiple_choice', 'easy', 'group_specific', '[{"question":"On February 12, 2019, ITZY debuted with a single album. What was it called?","options":["It''z Itzy","Voltage","It''z Me","It''z Different"],"correct":3,"fun_fact":"It held just two songs: the lead single Dalla Dalla and a second track, Want It?","source":"https://en.wikipedia.org/wiki/It%27z_Different"},{"question":"The name ITZY comes from a Korean word. What does that word mean?","options":["To shine","To dream","To fly","To have"],"correct":3,"fun_fact":"Lia has tied the name to All in us, a line the members repeat often: the idea is that ITZY already holds whatever fans hope to find.","source":"https://en.wikipedia.org/wiki/Itzy"},{"question":"Which single led ITZY''s first EP, released on July 29, 2019?","options":["Not Shy","Wannabe","Icy","Loco"],"correct":2,"fun_fact":"It became the group''s first No. 1 on Billboard''s K-pop Hot 100 and picked up twelve music show trophies.","source":"https://en.wikipedia.org/wiki/Icy_(Itzy_song)"},{"question":"Which ITZY single from August 2020 was described as the group''s first love-themed song?","options":["Wannabe","Icy","Not Shy","Loco"],"correct":2,"fun_fact":"An English version arrived in January 2021, with a music video starring 3D Zepeto avatars of the five members.","source":"https://en.wikipedia.org/wiki/Not_Shy_(song)"},{"question":"In the Morning, also called Mafia in the Morning, was the lead single of which 2021 ITZY EP?","options":["Not Shy","Guess Who","It''z Me","Checkmate"],"correct":1,"fun_fact":"The title is a nod to Mafia, the party game, and J.Y. Park is one of the song''s writers.","source":"https://en.wikipedia.org/wiki/In_the_Morning_(Itzy_song)"},{"question":"Which ITZY single was nominated for Best K-Pop at the 2022 MTV Video Music Awards?","options":["Wannabe","Loco","Sneakers","Cake"],"correct":1,"fun_fact":"ITZY also sang it on The Kelly Clarkson Show on September 27, 2021, three days after its release.","source":"https://en.wikipedia.org/wiki/Loco_(Itzy_song)"},{"question":"Which 2022 EP became ITZY''s first album certified Million in South Korea?","options":["Cheshire","Gold","Crazy in Love","Checkmate"],"correct":3,"fun_fact":"In the US it opened at No. 8 on the Billboard 200 with 33,000 units, the group''s first album to reach the top ten there.","source":"https://en.wikipedia.org/wiki/Checkmate_(EP)"},{"question":"Cake, a summer single from July 2023, was the lead single of which ITZY EP?","options":["Cheshire","Gold","Kill My Doubt","Guess Who"],"correct":2,"fun_fact":"The producing duo Black Eyed Pilseung wrote and composed it, and it took first place on Music Bank on August 11, 2023.","source":"https://en.wikipedia.org/wiki/Cake_(Itzy_song)"},{"question":"Which single led ITZY''s January 2024 EP Born to Be?","options":["Untouchable","Gold","Cake","Sneakers"],"correct":0,"fun_fact":"Bang Hye-hyun and Lee Seu-ran wrote the lyrics, and the song won on Music Bank on January 19, 2024.","source":"https://en.wikipedia.org/wiki/Untouchable_(Itzy_song)"},{"question":"Which ITZY member was cast by JYP Entertainment at a GOT7 fan event?","options":["Ryujin","Chaeryeong","Yeji","Yuna"],"correct":0,"fun_fact":"Before the debut, she and Yuna appeared in BTS''s Love Yourself highlight reel in 2017.","source":"https://en.wikipedia.org/wiki/Ryujin_(rapper)"}]'::jsonb, '2026-12-03'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Itzy ; https://www.wikidata.org/wiki/Q60732823 ; https://en.wikipedia.org/wiki/It%27z_Different ; https://www.nme.com/features/music-interviews/itzy-interview-crazy-in-love-loco-3059287 ; https://en.wikipedia.org/wiki/Icy_(Itzy_song) ; https://en.wikipedia.org/wiki/Not_Shy_(song) ; https://en.wikipedia.org/wiki/In_the_Morning_(Itzy_song) ; https://en.wikipedia.org/wiki/Loco_(Itzy_song) ; https://en.wikipedia.org/wiki/MTV_Video_Music_Award_for_Best_K-Pop ; https://en.wikipedia.org/wiki/Checkmate_(EP) ; https://en.wikipedia.org/wiki/Cake_(Itzy_song) ; https://en.wikipedia.org/wiki/Untouchable_(Itzy_song) ; https://en.wikipedia.org/wiki/Born_to_Be_(EP) ; https://en.wikipedia.org/wiki/Ryujin_(rapper). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop Idol MCs Through the Years', 'Idols who hosted Korea''s weekly music shows from 2011 to 2024. Can you match each one to the right stage?', null, 'multiple_choice', 'easy', 'knowledge', '[{"question":"Which show did IVE''s Jang Won-young co-host with ENHYPEN''s Sunghoon from October 2021?","options":["Music Bank","M Countdown","Inkigayo","Show! Music Core"],"correct":0,"fun_fact":"Their pairing lasted until September 2022, and Lee Chae-min then hosted alongside her until January 2023.","source":"https://en.wikipedia.org/wiki/Music_Bank"},{"question":"Which SISTAR member co-hosted Music Bank with actor Park Seo-joon from 2013 to 2015?","options":["Soyou","Bora","Hyolyn","Dasom"],"correct":1,"fun_fact":"The pair took over in October 2013 from Jeong Jinwoon and Park Se-young, who had hosted since that April.","source":"https://en.wikipedia.org/wiki/Music_Bank"},{"question":"IU was a regular host of which weekly music show from 2011 to 2013?","options":["Inkigayo","M Countdown","Show Champion","Music Bank"],"correct":0,"fun_fact":"Over those years her co-hosts included Jo Kwon, Lee Gi-kwang, Lee Jong-suk and Hwang Kwang-hee.","source":"https://en.wikipedia.org/wiki/Inkigayo"},{"question":"Which SEVENTEEN member hosted Inkigayo from February 2018 to October 2019?","options":["Hoshi","Seungkwan","Mingyu","DK"],"correct":2,"fun_fact":"He started next to Jung Chae-yeon and Song Kang, and ended his run alongside Shin Eun-soo.","source":"https://en.wikipedia.org/wiki/Inkigayo"},{"question":"Taeyeon, Tiffany and Seohyun of Girls'' Generation co-hosted which show from 2012 to 2013?","options":["Music Bank","Inkigayo","Show! Music Core","M Countdown"],"correct":2,"fun_fact":"Tiffany had already hosted the same program with Yuri, from April 2009 to July 2010.","source":"https://en.wikipedia.org/wiki/Show!_Music_Core"},{"question":"Which ASTRO member hosted Show! Music Core from October 2016 to February 2018?","options":["Rocky","MJ","Jinjin","Cha Eun-woo"],"correct":3,"fun_fact":"From April 2017 his co-host was Xiyeon, and he came back to the show for a short stint in early 2019.","source":"https://en.wikipedia.org/wiki/Show!_Music_Core"},{"question":"Which show did SHINee''s Key host from March 2015 to April 2017, alone in his final months?","options":["The Show","M Countdown","Music Bank","Inkigayo"],"correct":1,"fun_fact":"After he left, the show turned to guest MCs, starting with EXID''s Hani and Pristin''s Kyulkyung and Nayoung on April 20, 2017.","source":"https://en.wikipedia.org/wiki/M_Countdown"},{"question":"Which member of (G)I-DLE, now i-dle, hosted M Countdown from February 2021 to November 2023?","options":["Soyeon","Miyeon","Yuqi","Minnie"],"correct":1,"fun_fact":"Her co-hosts over that stretch were Nam Yoon-su, then Joohoney, then Sung Han-bin.","source":"https://en.wikipedia.org/wiki/M_Countdown"},{"question":"Which f(x) member co-hosted Show Champion through 2013?","options":["Luna","Krystal","Victoria","Amber"],"correct":3,"fun_fact":"From January to August 2013 she shared hosting duties with Hahm Eun-jung.","source":"https://en.wikipedia.org/wiki/Show_Champion"},{"question":"Which ATEEZ member hosted The Show from March 2021 to March 2024?","options":["Yeosang","San","Wooyoung","Jongho"],"correct":0,"fun_fact":"He started with Kim Yo-han and Weeekly''s Jihan, and his set of co-hosts changed twice during those three years.","source":"https://en.wikipedia.org/wiki/The_Show_(South_Korean_TV_program)"}]'::jsonb, '2026-12-04'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Music_Bank ; https://en.wikipedia.org/wiki/Inkigayo ; https://en.wikipedia.org/wiki/Show!_Music_Core ; https://en.wikipedia.org/wiki/M_Countdown ; https://en.wikipedia.org/wiki/Miyeon ; https://en.wikipedia.org/wiki/Show_Champion ; https://en.wikipedia.org/wiki/The_Show_(South_Korean_TV_program). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('EXO: The XOXO Era', 'Ten questions on EXO''s 2013 XOXO era: the Wolf single, the Growl repackage, the two editions, the charts and the year-end awards.', 8, 'multiple_choice', 'medium', 'era', '[{"question":"XOXO came in a Korean edition called Kiss and a Mandarin edition called what?","options":["Love","Hug","Wink","Heart"],"correct":1,"fun_fact":"Both editions came out on June 3, 2013, and the album climbed to No. 1 on Billboard''s World Albums chart.","source":"https://en.wikipedia.org/wiki/XOXO_(Exo_album)"},{"question":"Wolf''s full Korean title translates into English as what?","options":["The Lone Wolf","Night of the Wolf","The Wolf and the Moon","The Wolf and the Beauty"],"correct":3,"fun_fact":"Its sound blends dubstep into hip-hop, and its story pairs a werewolf with a beautiful woman in a tragic romance.","source":"https://en.wikipedia.org/wiki/Wolf_(Exo_song)"},{"question":"Which XOXO song was the first that all twelve EXO members recorded together?","options":["Let Out the Beast","Black Pearl","Wolf","Baby Don''t Cry"],"correct":2,"fun_fact":"It peaked at No. 10 on the Gaon Digital Chart and at No. 4 on Billboard''s World Digital Songs chart.","source":"https://en.wikipedia.org/wiki/Wolf_(Exo_song)"},{"question":"The Growl repackage, released on August 5, 2013, added how many new tracks to XOXO?","options":["One","Two","Three","Five"],"correct":2,"fun_fact":"In South Korea the original album sold over 570,000 copies and the repackage over 760,000.","source":"https://en.wikipedia.org/wiki/XOXO_(Exo_album)"},{"question":"Growl''s first music videos, out on August 1, 2013, show EXO performing in what kind of place?","options":["A subway station","A school classroom","A forest at night","A dimly lit warehouse"],"correct":3,"fun_fact":"Styled to look like one unbroken take, they were followed on August 20, 2013 by a second set shot somewhere else.","source":"https://en.wikipedia.org/wiki/Growl_(song)"},{"question":"How many first-place trophies did Growl win on South Korean music shows?","options":["6","9","11","14"],"correct":3,"fun_fact":"The wins came on Music Bank, Inkigayo, Show Champion, M Countdown and Show! Music Core.","source":"https://en.wikipedia.org/wiki/Growl_(song)"},{"question":"Growl won the Song of the Year daesang at the 2013 edition of which awards show?","options":["Mnet Asian Music Awards","Golden Disc Awards","Melon Music Awards","Korean Music Awards"],"correct":2,"fun_fact":"The ceremony took place on November 14, 2013 at the Olympic Gymnastics Arena, and EXO left with three awards, the most of the night.","source":"https://en.wikipedia.org/wiki/2013_Melon_Music_Awards"},{"question":"XOXO took which top prize at the 28th Golden Disc Awards in January 2014?","options":["Disc Daesang","Digital Daesang","Rookie of the Year","Popularity Award"],"correct":0,"fun_fact":"XOXO also took an album Bonsang at that ceremony, held at Kyung Hee University in Seoul.","source":"https://en.wikipedia.org/wiki/28th_Golden_Disc_Awards"},{"question":"Growl peaked at which position on the Gaon Digital Chart?","options":["No. 1","No. 2","No. 5","No. 10"],"correct":1,"fun_fact":"It also climbed to No. 3 on both Billboard''s K-pop Hot 100 and its World Digital Songs chart.","source":"https://en.wikipedia.org/wiki/Growl_(song)"},{"question":"Which SM songwriter wrote Wolf''s Korean lyrics and co-composed the song?","options":["Kenzie","Yoo Young-jin","Hitchhiker","Hwang Hyun"],"correct":0,"fun_fact":"Kenzie also co-produced the track with Will Simms, while Zhou Weijie wrote the Mandarin lyrics.","source":"https://en.wikipedia.org/wiki/Wolf_(Exo_song)"}]'::jsonb, '2026-12-05'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/XOXO_(Exo_album) ; https://musicbrainz.org/release/16888bbd-7d3f-459f-bfee-299070fc0c4e ; https://musicbrainz.org/release/eec94b88-9ef4-4713-b500-a48294654cbd ; https://en.wikipedia.org/wiki/Exo ; https://en.wikipedia.org/wiki/Wolf_(Exo_song) ; https://en.wikipedia.org/wiki/Growl_(song) ; https://en.wikipedia.org/wiki/2013_Melon_Music_Awards ; https://en.wikipedia.org/wiki/28th_Golden_Disc_Awards ; https://www.koreajoongangdaily.com/korea/psy-exo-take-top-prizes-at-28th-golden-disks/10983706. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop Songs With a Flower in the Title', 'Ten K-pop songs with a flower in the title, from cherry blossoms and lilacs to daisies and sunflowers. How well do you know them?', null, 'multiple_choice', 'easy', 'fun', '[{"question":"Lilac (2021) shares its name with the fifth studio album of which singer?","options":["IU","Taeyeon","Chungha","BoA"],"correct":0,"fun_fact":"Out on March 25, 2021, it draws on 1970s and 1980s disco, and IU compared the song to a typhoon in springtime.","source":"https://en.wikipedia.org/wiki/Lilac_(IU_album)"},{"question":"Which band''s Cherry Blossom Ending climbs back up the Korean charts almost every spring?","options":["Busker Busker","Hyukoh","The Rose","Day6"],"correct":0,"fun_fact":"Member Jang Beom-june wrote it, and the band first became known as runner-up on Superstar K3 in 2011.","source":"https://en.wikipedia.org/wiki/Cherry_Blossom_Ending"},{"question":"Which boy group released Daisy in October 2020 as the lead single of its EP WE:TH?","options":["SF9","Pentagon","Victon","Golden Child"],"correct":1,"fun_fact":"Members Hui and Wooseok co-wrote it, and its choreography includes a move called the Sowing Dance.","source":"https://en.wikipedia.org/wiki/Daisy_(Pentagon_song)"},{"question":"Wind Flower (2018), the lead single of the EP Blue;s, is by which girl group?","options":["Lovelyz","Mamamoo","Oh My Girl","GFriend"],"correct":1,"fun_fact":"Moonbyul helped write it, and a Japanese version came out as a single in February 2019.","source":"https://en.wikipedia.org/wiki/Wind_Flower"},{"question":"Which Red Velvet member made her solo debut with Like a Flower in November 2024?","options":["Seulgi","Wendy","Joy","Irene"],"correct":3,"fun_fact":"SM released the song with its EP on November 26, 2024, and Irene performed it on Music Bank, Show! Music Core and Inkigayo in the days after.","source":"https://en.wikipedia.org/wiki/Like_a_Flower_(song)"},{"question":"RM''s Wild Flower, the title track of his album Indigo, features Youjeen of which rock band?","options":["YB","Nell","Jaurim","Cherry Filter"],"correct":3,"fun_fact":"It came out on December 2, 2022, and Indigo was RM''s debut studio album.","source":"https://en.wikipedia.org/wiki/Wild_Flower_(RM_song)"},{"question":"Rose led the 2021 debut EP Empathy of which EXO member?","options":["Kai","Baekhyun","D.O.","Suho"],"correct":2,"fun_fact":"The song was first written in English, and the singer translated the lyrics into Korean himself.","source":"https://en.wikipedia.org/wiki/Rose_(D.O._song)"},{"question":"Sunflower, a 2022 single album, was the solo debut of which I.O.I member?","options":["Somi","Chungha","Sejeong","Yoojung"],"correct":3,"fun_fact":"After I.O.I''s first run ended in 2017, she debuted with Weki Meki that August.","source":"https://en.wikipedia.org/wiki/Choi_Yoo-jung_(singer)"},{"question":"Which singer released Flower Shower in November 2019, her first song with P Nation?","options":["Sunmi","Hyolyn","Hyuna","Heize"],"correct":2,"fun_fact":"Psy and Hyuna wrote the lyrics together, and the song later appeared on her seventh EP, I''m Not Cool.","source":"https://en.wikipedia.org/wiki/Flower_Shower"},{"question":"Jisoo''s Flower blends traditional Korean melodies with elements of which region''s music?","options":["Celtic","Caribbean","Andean","Nordic"],"correct":1,"fun_fact":"Released on March 31, 2023, it peaked at No. 2 on both the Billboard Global 200 and the Circle Digital Chart.","source":"https://en.wikipedia.org/wiki/Flower_(Jisoo_song)"}]'::jsonb, '2026-12-06'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Lilac_(IU_song) ; https://en.wikipedia.org/wiki/Lilac_(IU_album) ; https://en.wikipedia.org/wiki/Cherry_Blossom_Ending ; https://en.wikipedia.org/wiki/Daisy_(Pentagon_song) ; https://en.wikipedia.org/wiki/Wind_Flower ; https://en.wikipedia.org/wiki/Like_a_Flower_(song) ; https://en.wikipedia.org/wiki/Wild_Flower_(RM_song) ; https://en.wikipedia.org/wiki/Rose_(D.O._song) ; https://en.wikipedia.org/wiki/Empathy_(EP) ; https://en.wikipedia.org/wiki/Choi_Yoo-jung_(singer) ; https://en.wikipedia.org/wiki/Sunflower_(single_album) ; https://en.wikipedia.org/wiki/Flower_Shower ; https://en.wikipedia.org/wiki/I%27m_Not_Cool ; https://en.wikipedia.org/wiki/Flower_(Jisoo_song). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('GOT7 True or False', 'Ten true or false statements on GOT7''s story, from the 2014 debut and the Japanese releases to the group''s 2022 EP.', 21, 'true_false', 'medium', 'true_false', '[{"question":"Before GOT7, Jay B and Jinyoung debuted in 2012 as the duo JJ Project.","correct":true,"fun_fact":"The duo''s single album Bounce came out on May 20, 2012, after the pair had acted in the drama Dream High 2.","source":"https://en.wikipedia.org/wiki/JJ_Project"},{"question":"Get7 was a working name for the group before JYP settled on Got7 in December 2013.","correct":true,"fun_fact":"J.Y. Park linked the name to g.o.d: he was once meant to debut with that group, whose working name was Got6.","source":"https://en.wikipedia.org/wiki/Got7"},{"question":"GOT7''s debut single, Girls Girls Girls, samples an exclamation from Wonder Girls'' hit Tell Me.","correct":true,"fun_fact":"J.Y. Park wrote and composed it, and GOT7 first performed it on M Countdown on January 16, 2014.","source":"https://en.wikipedia.org/wiki/Girls_Girls_Girls_(Got7_song)"},{"question":"Got It?, GOT7''s debut EP, peaked at No. 1 on South Korea''s Gaon Album Chart.","correct":false,"fun_fact":"It stopped at No. 2 in Korea, but it did reach No. 1 on Billboard''s World Albums chart.","source":"https://en.wikipedia.org/wiki/Got_It%3F"},{"question":"GOT7 made their Japanese debut in 2016 with the album Moriagatteyo.","correct":false,"fun_fact":"Their Japanese debut was the single Around the World on October 22, 2014. Moriagatteyo, out in February 2016, was their first Japanese studio album.","source":"https://en.wikipedia.org/wiki/Got7"},{"question":"Just Right was the lead single of GOT7''s first studio album, Identify.","correct":false,"fun_fact":"Identify, released in November 2014, was led by Stop Stop It. Just Right was the title track of a separate EP in July 2015.","source":"https://en.wikipedia.org/wiki/Got7"},{"question":"J.Y. Park wrote and composed GOT7''s 2016 single Hard Carry.","correct":false,"fun_fact":"Earattack and Yoogeun wrote the lyrics and composed it with Lish. GOT7 first performed it on M Countdown on September 29, 2016.","source":"https://en.wikipedia.org/wiki/Hard_Carry"},{"question":"The album Present: You includes Lullaby in Korean, English, Chinese and Japanese.","correct":false,"fun_fact":"The fourth language was Spanish, and on the 2018 album each member also has a solo song he co-produced.","source":"https://en.wikipedia.org/wiki/Present:_You"},{"question":"In February 2021, a month after leaving JYP Entertainment, GOT7 released the single Encore.","correct":true,"fun_fact":"It came out on February 20, 2021 through Warner Music Korea.","source":"https://en.wikipedia.org/wiki/Got7"},{"question":"GOT7''s 2022 self-titled EP was led by the song Nanana.","correct":true,"fun_fact":"Released on May 23, 2022, the six-track EP followed the Got7 Homecoming 2022 FanCon held in Seoul on May 21 and 22.","source":"https://en.wikipedia.org/wiki/Got7_(EP)"}]'::jsonb, '2026-12-07'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Got7 ; https://www.wikidata.org/wiki/Q23772001 ; https://en.wikipedia.org/wiki/JJ_Project ; https://en.wikipedia.org/wiki/Girls_Girls_Girls_(Got7_song) ; https://en.wikipedia.org/wiki/Got_It%3F ; https://en.wikipedia.org/wiki/Got7_discography ; https://en.wikipedia.org/wiki/Identify_(album) ; https://en.wikipedia.org/wiki/Hard_Carry ; https://en.wikipedia.org/wiki/Present:_You ; https://en.wikipedia.org/wiki/Got7_(EP). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('MAMAMOO: From Mr. Ambiguous to Starry Night', 'From their 2014 debut EP to Starry Night, Hip, Mamamoo+ and solo careers: ten questions on MAMAMOO''s music and milestones.', 22, 'multiple_choice', 'medium', 'group_specific', '[{"question":"Mr. Ambiguous led MAMAMOO''s June 2014 debut EP. What was that EP called?","options":["Hello","Piano Man","Purple","Memory"],"correct":0,"fun_fact":"The song turned out to be a surprise success for the members, who had expected its very personal style to limit its reach.","source":"https://en.wikipedia.org/wiki/Hello_(Mamamoo_EP)"},{"question":"Um Oh Ah Yeh, MAMAMOO''s 2015 sleeper hit, was the lead single of which EP?","options":["Pink Funky","Piano Man","Memory","Purple"],"correct":0,"fun_fact":"Solar, Moonbyul and Hwasa share writing credits on it, and the video has three members disguised as men, complete with wigs and beards.","source":"https://en.wikipedia.org/wiki/Pink_Funky"},{"question":"In August 2016, MAMAMOO split into a vocal pair and a rap pair for two singles. Who formed the rap pair?","options":["Solar and Wheein","Wheein and Hwasa","Moonbyul and Hwasa","Solar and Moonbyul"],"correct":2,"fun_fact":"The rap pair released Dab Dab, while Solar and Wheein put out Angel on the same day, August 31, 2016.","source":"https://en.wikipedia.org/wiki/Mamamoo"},{"question":"Which MAMAMOO song did the group re-record in Japanese for its first Japanese single in October 2018?","options":["Décalcomanie","Starry Night","Um Oh Ah Yeh","Yes I Am"],"correct":0,"fun_fact":"The Korean original had led their 2016 EP Memory, and the Japanese single reached No. 11 on the weekly Oricon Singles Chart.","source":"https://en.wikipedia.org/wiki/Mamamoo"},{"question":"Starry Night (2018) led which EP, MAMAMOO''s first No. 1 on the Gaon Album Chart?","options":["Red Moon","White Wind","Yellow Flower","Blue;s"],"correct":2,"fun_fact":"That EP opened the Four Seasons, Four Colors series, which continued in July 2018 with Red Moon and its lead single Egotistic.","source":"https://en.wikipedia.org/wiki/Mamamoo"},{"question":"MAMAMOO released Hip in November 2019, soon after winning which Mnet competition show?","options":["Road to Kingdom","Queendom","Girls Planet 999","Produce 48"],"correct":1,"fun_fact":"Hip went on to give the group its first No. 1 on Billboard''s World Digital Song Sales chart.","source":"https://en.wikipedia.org/wiki/Hip_(song)"},{"question":"Which MAMAMOO member made her solo debut in April 2018 with Easy, featuring Sik-K?","options":["Moonbyul","Solar","Wheein","Hwasa"],"correct":2,"fun_fact":"Easy peaked at No. 3 in South Korea, and her first studio album, In the Mood, followed in October 2023.","source":"https://en.wikipedia.org/wiki/Wheein"},{"question":"Which two members formed Mamamoo+, the group''s first official subunit, in 2022?","options":["Moonbyul and Hwasa","Wheein and Hwasa","Solar and Wheein","Solar and Moonbyul"],"correct":3,"fun_fact":"Two Rabbits was one of the names the duo weighed before choosing Mamamoo+, and it ended up as the title of their first EP in August 2023.","source":"https://en.wikipedia.org/wiki/Mamamoo%2B"},{"question":"What was the name of MAMAMOO''s first world tour, which ran from 2022 to 2023?","options":["4Seasons F/W","My Con World Tour","Moosical","4ward World Tour"],"correct":1,"fun_fact":"It opened with three Seoul shows in November 2022, went through Asia and the United States, and closed with encore concerts in Seoul in June 2023.","source":"https://en.wikipedia.org/wiki/Mamamoo"},{"question":"Solar starred in the 2024 Korean run of the musical Notre-Dame de Paris. Which role did she play?","options":["Fleur-de-Lys","Elphaba","Christine","Esmeralda"],"correct":3,"fun_fact":"The part earned her a Female Rookie of the Year nomination at the 18th Daegu International Musical Awards in July 2024.","source":"https://en.wikipedia.org/wiki/Solar_(singer)"}]'::jsonb, '2026-12-08'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Hello_(Mamamoo_EP) ; https://en.wikipedia.org/wiki/Pink_Funky ; https://en.wikipedia.org/wiki/Mamamoo ; https://en.wikipedia.org/wiki/Hip_(song) ; https://en.wikipedia.org/wiki/Wheein ; https://en.wikipedia.org/wiki/Mamamoo%2B ; https://en.wikipedia.org/wiki/Solar_(singer). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('SHINee: The Odd Era of 2015', 'SHINee in 2015: the album Odd, its lead single View, the August repackage, a year-end award and the tour where View premiered.', 23, 'multiple_choice', 'medium', 'era', '[{"question":"Ahead of View''s release, which member said he was worried about how its new sound would be received?","options":["Onew","Key","Taemin","Minho"],"correct":3,"fun_fact":"His worry came from how far the style strayed from their earlier songs, a contrast the album title Odd points to.","source":"https://en.wikipedia.org/wiki/View_(Shinee_song)"},{"question":"View, the lead single of Odd, is built mainly on which dance genre?","options":["Trap","Moombahton","Drum and bass","Deep house"],"correct":3,"fun_fact":"Its lyrics are about love sharpening every sense, and Billboard later named it among the greatest K-pop songs of the 2010s.","source":"https://en.wikipedia.org/wiki/View_(Shinee_song)"},{"question":"Which SHINee member wrote the lyrics of View?","options":["Key","Jonghyun","Minho","Onew"],"correct":1,"fun_fact":"He also helped write and compose Odd Eye, the R&B track that opens the album.","source":"https://en.wikipedia.org/wiki/Odd_(album)"},{"question":"Who created the choreography for View?","options":["Misha Gabriel","Tony Testa","Rino Nakasone","Ian Eastwood"],"correct":3,"fun_fact":"Instead of SHINee''s trademark sharp, tightly drilled moves, he built the routine around a relaxed groove that highlights how the members work together.","source":"https://en.wikipedia.org/wiki/Shinee"},{"question":"In which country was the music video for View filmed?","options":["Thailand","Australia","Japan","United States"],"correct":0,"fun_fact":"No video by a South Korean act drew more YouTube views in May 2015, and in it a crowd of female fans carries the members off.","source":"https://en.wikipedia.org/wiki/View_(Shinee_song)"},{"question":"On which music show did View win its first trophy, on May 27, 2015?","options":["Show Champion","Music Bank","Inkigayo","M Countdown"],"correct":0,"fun_fact":"The song collected nine music show wins in all, the last of them on The Show on June 9, 2015.","source":"https://en.wikipedia.org/wiki/Odd_(album)"},{"question":"What title did SHINee give the August 2015 repackage of Odd, which added four new songs?","options":["Atlantis","1 and 1","Married to the Music","The Story of Light Epilogue"],"correct":2,"fun_fact":"Billboard''s Jeff Benjamin heard its title track move from a beatbox-heavy hip hop opening to a funk chorus with horn blasts.","source":"https://en.wikipedia.org/wiki/Odd_(album)"},{"question":"Which award did View win at the 2015 Mnet Asian Music Awards?","options":["Song of the Year","Album of the Year","Best Dance Performance, Male Group","Best Male Group"],"correct":2,"fun_fact":"View was also up for Song of the Year that night, and later for the Digital Bonsang at the 30th Golden Disc Awards.","source":"https://en.wikipedia.org/wiki/View_(Shinee_song)"},{"question":"Which member''s ideas inspired the vintage, old-school costumes SHINee wore in the Odd era?","options":["Key","Minho","Taemin","Onew"],"correct":0,"fun_fact":"By his account, Odd was also the first time the group helped steer its own album, down to choosing the concept and the lead single.","source":"https://en.wikipedia.org/wiki/Shinee"},{"question":"SHINee first performed View live at the Seoul opening of which concert tour, in May 2015?","options":["SHINee World 2016","SHINee World IV","SHINee World V","SHINee World III"],"correct":1,"fun_fact":"It opened with three nights in Seoul in mid-May 2015 and wrapped up in Shanghai five months later.","source":"https://en.wikipedia.org/wiki/Shinee_World_IV"}]'::jsonb, '2026-12-09'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Odd_(album) ; https://en.wikipedia.org/wiki/View_(Shinee_song) ; https://en.wikipedia.org/wiki/Shinee ; https://en.wikipedia.org/wiki/Shinee_World_IV. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop Songs of 2015', 'Ten singles from 2015, from Crazy in February to Daddy at year''s end: can you match each song to the act that released it?', null, 'multiple_choice', 'medium', 'knowledge', '[{"question":"Which girl group released Crazy, the title track of its sixth EP, in February 2015?","options":["Brown Eyed Girls","EXID","4Minute","Secret"],"correct":2,"fun_fact":"The EP topped Billboard''s World Albums chart, and the ballad Cold Rain had come out first, in January 2015.","source":"https://en.wikipedia.org/wiki/Crazy_(4Minute_EP)"},{"question":"Only You, the lead single of the March 2015 EP Colors, was released by which girl group?","options":["Sistar","AOA","Girl''s Day","miss A"],"correct":3,"fun_fact":"Black Eyed Pilseung composed it and co-wrote its lyrics, and it held No. 1 on the Gaon Digital Chart for two weeks.","source":"https://en.wikipedia.org/wiki/Only_You_(Miss_A_song)"},{"question":"Shake It, produced by Duble Sidekick, was a June 2015 single by which girl group?","options":["Apink","EXID","Sistar","AOA"],"correct":2,"fun_fact":"Its first trophy came on M Countdown on July 2, 2015, followed by wins on Music Bank, Inkigayo and Show Champion.","source":"https://en.wikipedia.org/wiki/Shake_It_(EP)"},{"question":"Remember, a July 2015 single co-written by Shinsadong Tiger, came from which girl group?","options":["Lovelyz","GFriend","Oh My Girl","Apink"],"correct":3,"fun_fact":"It was the title track of Pink Memory, the group''s second full-length album.","source":"https://en.wikipedia.org/wiki/Pink_Memory"},{"question":"Hoya of Infinite makes a cameo in the video for which girl group''s 2015 hit Ah-Choo?","options":["Lovelyz","Oh My Girl","CLC","April"],"correct":0,"fun_fact":"Ah-Choo led the group''s first EP in October 2015 and was still on major Korean charts in early 2016.","source":"https://en.wikipedia.org/wiki/Lovelyz"},{"question":"Which YG boy group debuted with the single My Type on September 15, 2015?","options":["Monsta X","WINNER","iKON","SEVENTEEN"],"correct":2,"fun_fact":"Its video drew over 1.7 million YouTube views in a day, and it won on Music Core on September 26, before the group''s first official live stage.","source":"https://en.wikipedia.org/wiki/Welcome_Back_(iKon_album)"},{"question":"Which singer released Mind Your Own Business as the title track of her first full-length album, Vivid, in 2015?","options":["Lee Hi","Ailee","Hyolyn","Baek A-yeon"],"correct":1,"fun_fact":"Show Champion gave the Vivid era its first music show win on October 7, 2015, just a week after the album came out.","source":"https://en.wikipedia.org/wiki/Vivid_(Ailee_album)"},{"question":"Which singer made her solo debut in October 2015 with I, an EP led by a song of the same name?","options":["IU","Taeyeon","Sunmi","Hyuna"],"correct":1,"fun_fact":"Rapper Verbal Jint features on the title track, and the EP entered Billboard''s World Albums chart at No. 1.","source":"https://en.wikipedia.org/wiki/I_(Taeyeon_EP)"},{"question":"Chained Up, the title track of a second studio album released in November 2015, is by which boy group?","options":["VIXX","Infinite","B.A.P","BTOB"],"correct":0,"fun_fact":"It took its first music show win on The Show on November 17, 2015, and the album opened at No. 3 on Billboard''s World Albums chart.","source":"https://en.wikipedia.org/wiki/Chained_Up"},{"question":"Who released Daddy, a single featuring CL of 2NE1, at the end of 2015?","options":["G-Dragon","Psy","Zico","Jay Park"],"correct":1,"fun_fact":"It borrows a hook from will.i.am''s 2007 song I Got It from My Mama and became his third No. 1 on the Gaon Digital Chart.","source":"https://en.wikipedia.org/wiki/Daddy_(Psy_song)"}]'::jsonb, '2026-12-10'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Crazy_(4Minute_EP) ; https://en.wikipedia.org/wiki/Only_You_(Miss_A_song) ; https://en.wikipedia.org/wiki/Shake_It_(EP) ; https://en.wikipedia.org/wiki/Pink_Memory ; https://en.wikipedia.org/wiki/Lovelyz ; https://en.wikipedia.org/wiki/Welcome_Back_(iKon_album) ; https://en.wikipedia.org/wiki/Vivid_(Ailee_album) ; https://en.wikipedia.org/wiki/I_(Taeyeon_EP) ; https://en.wikipedia.org/wiki/Chained_Up ; https://en.wikipedia.org/wiki/Daddy_(Psy_song) ; https://en.wikipedia.org/wiki/Ailee. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop Songs on the Phone', 'Texts to a crush, a phone promo, an ex who should not call and a wrong number: ten K-pop songs and releases tied to calls, texts and mobiles.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"IU''s 2018 single Bbibbi is named after the Korean word for which device?","options":["A fax machine","A walkie-talkie","A pager","A landline"],"correct":2,"fun_fact":"IU released it partly to mark ten years since her debut, and it entered the Gaon Digital Chart at No. 1.","source":"https://en.wikipedia.org/wiki/Bbibbi"},{"question":"Which group shot the video for its 2023 single ETA entirely on an iPhone 14 Pro?","options":["LE SSERAFIM","IVE","NewJeans","aespa"],"correct":2,"fun_fact":"Made with Apple, the video was filmed in Barcelona, and the song itself is an upbeat Baltimore club track.","source":"https://en.wikipedia.org/wiki/ETA_(song)"},{"question":"Which boy band released Wrong Number as a single in 2008?","options":["Super Junior","TVXQ","BIGBANG","SS501"],"correct":1,"fun_fact":"It was the second of two promoted singles from the album Mirotic, coming after the title song.","source":"https://en.wikipedia.org/wiki/Mirotic_(album)"},{"question":"Call Call Call! was the lead single of the first Japanese EP by which boy band, released in May 2018?","options":["SEVENTEEN","NCT 127","Stray Kids","The Boyz"],"correct":0,"fun_fact":"Released by Pledis Japan, We Make You climbed as high as second place on Oricon''s weekly ranking and lasted 74 weeks on it.","source":"https://en.wikipedia.org/wiki/We_Make_You"},{"question":"Which girl group joined BIGBANG on Lollipop, a 2009 song made to promote an LG phone?","options":["KARA","Girls'' Generation","2NE1","Wonder Girls"],"correct":2,"fun_fact":"It borrows from the 1958 hit of the same name, and it spent four weeks at No. 1 on the Mnet music portal.","source":"https://en.wikipedia.org/wiki/Lollipop_(BigBang_and_2NE1_song)"},{"question":"Don''t Text Me is a track on I Am, the May 2018 debut EP of which girl group?","options":["Weki Meki","fromis_9","LOONA","(G)I-DLE"],"correct":3,"fun_fact":"The six-track EP was led by Latata, which member Soyeon composed with Big Sancho.","source":"https://en.wikipedia.org/wiki/I_Am_(EP)"},{"question":"Which Super Junior member sang Whatcha Doin'', a 2018 duet with Chung Ha about failing to reach someone?","options":["Yesung","Donghae","Ryeowook","Kyuhyun"],"correct":0,"fun_fact":"The Korean title translates as Where are you now?, and he co-wrote the lyrics with Min Yeon-jae.","source":"https://en.wikipedia.org/wiki/Whatcha_Doin%27_(song)"},{"question":"Which boy group set up a hotline with member voice messages before its November 2024 single album Last Bell?","options":["RIIZE","TWS","BOYNEXTDOOR","ZEROBASEONE"],"correct":1,"fun_fact":"Demand swamped the line: within 10 minutes of the number going up, more than 10,000 fans got through and tens of thousands more calls failed.","source":"https://en.wikipedia.org/wiki/Last_Bell"},{"question":"Which boy band released Don''t Call Me, a 2021 song warning an ex not to phone again?","options":["SHINee","NCT 127","Super Junior","EXO"],"correct":0,"fun_fact":"The song was first meant for their labelmate BoA, and it led their seventh Korean studio album, which shares its name.","source":"https://en.wikipedia.org/wiki/Don%27t_Call_Me_(Shinee_song)"},{"question":"IU''s 2019 hit Blueming, about sending little texts to a crush, was a single from which EP?","options":["Palette","Chat-Shire","Modern Times","Love Poem"],"correct":3,"fun_fact":"It debuted at No. 1 on the Gaon Digital Chart and won the Digital Daesang at the 35th Golden Disc Awards in January 2021.","source":"https://en.wikipedia.org/wiki/Blueming_(song)"}]'::jsonb, '2026-12-11'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Bbibbi ; https://en.wikipedia.org/wiki/ETA_(song) ; https://en.wikipedia.org/wiki/Mirotic_(album) ; https://en.wikipedia.org/wiki/We_Make_You ; https://en.wikipedia.org/wiki/I_Am_(EP) ; https://en.wikipedia.org/wiki/Whatcha_Doin%27_(song) ; https://en.wikipedia.org/wiki/Last_Bell ; https://en.wikipedia.org/wiki/Lollipop_(BigBang_and_2NE1_song) ; https://en.wikipedia.org/wiki/Don%27t_Call_Me_(Shinee_song) ; https://en.wikipedia.org/wiki/Shinee ; https://en.wikipedia.org/wiki/Blueming_(song). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('STAYC: From So Bad to Cheeky Icy Thang', 'STAYC basics: what their name means, their sound, their fandom, a 2025 tour and their singles and albums from 2021 to 2024.', 19, 'multiple_choice', 'easy', 'group_specific', '[{"question":"What does the name STAYC stand for?","options":["Stay Young Chic","Star to a Young Culture","Stars of Young Crush","Stay All Your Choices"],"correct":1,"fun_fact":"Before the name was announced, the trainees were known as High Up Girls, after their agency.","source":"https://en.wikipedia.org/wiki/STAYC"},{"question":"What was the name of STAYC''s second world tour, which opened in Seoul in April 2025?","options":["Stay Tuned","Stay Forever","Stay With Me","Stay Young"],"correct":0,"fun_fact":"Both Seoul shows, at Olympic Hall on April 12 and 13, sold out once general ticket sales opened.","source":"https://www.highup-ent.com/en/stayc-kicks-off-second-world-tour-stay-tuned-in-seoul-this-april-tickets-sell-out-instantly/"},{"question":"Before STAYC''s debut, which term did their producers use to describe the group''s sound?","options":["Teen Fresh","Teen Crush","Girl Crush","Fresh Pop"],"correct":0,"fun_fact":"The term joins teen and fresh to stress each member''s vocal color, and it later named a 2023 EP and their first world tour.","source":"https://en.wikipedia.org/wiki/STAYC"},{"question":"What is the name of STAYC''s fandom?","options":["STAY","Sweetie","SWITH","Starlight"],"correct":2,"fun_fact":"STAYC met SWITH at their first fan meeting, Stay Cool Party, held at Sejong University''s Ocean Hall on October 9, 2022.","source":"https://www.highup-ent.com/en/%EC%8A%A4%ED%85%8C%EC%9D%B4%EC%94%A8-%EB%8D%B0%EB%B7%94-%EC%B2%AB-%ED%8C%AC%EB%AF%B8%ED%8C%85-stay-cool-party-%EC%84%B1%EB%A3%8C-%EC%82%AC%EB%9E%91-%EB%8A%90%EA%BC%88/"},{"question":"Which song led Staydom, STAYC''s April 2021 single album?","options":["Bebe","Beautiful Monster","Like This","ASAP"],"correct":3,"fun_fact":"The ASAP video needed only nine days to hit 20 million views, and the song made it onto Billboard''s K-pop 100.","source":"https://en.wikipedia.org/wiki/STAYC"},{"question":"Which song gave STAYC their first music show trophy, on The Show in September 2021?","options":["So Bad","ASAP","Run2U","Stereotype"],"correct":3,"fun_fact":"It led their first EP, also called Stereotype, and its video hit 30 million views three weeks after release.","source":"https://en.wikipedia.org/wiki/STAYC"},{"question":"Run2U, released in February 2022, was the lead single of which STAYC EP?","options":["Young-Luv.com","We Need Love","Stay Alive","S"],"correct":0,"fun_fact":"It became their first album to debut at No. 1 on the Gaon Album Chart.","source":"https://en.wikipedia.org/wiki/STAYC"},{"question":"With which single did STAYC make their Japanese debut in November 2022?","options":["GPT","Bubble","Mwuah","Poppy"],"correct":3,"fun_fact":"Oricon''s weekly singles chart lists Poppy''s best position as No. 13, and the song also made the Billboard Japan Hot 100.","source":"https://en.wikipedia.org/wiki/STAYC"},{"question":"What was the title of STAYC''s February 2023 single album, named after its lead single?","options":["Bubble","Teddy Bear","Bebe","Beautiful Monster"],"correct":1,"fun_fact":"Described as a pop punk song with a hopeful message, the title track climbed to No. 4 on the Circle Digital Chart.","source":"https://en.wikipedia.org/wiki/Teddy_Bear_(STAYC_song)"},{"question":"Cheeky Icy Thang led STAYC''s first studio album in July 2024. What is the album called?","options":["Stay Alive","We Need Love","Metamorphic","I Want It"],"correct":2,"fun_fact":"The album holds 14 tracks, and the group ran a pop-up store in Seoul to celebrate its release.","source":"https://en.wikipedia.org/wiki/Metamorphic_(album)"}]'::jsonb, '2026-12-12'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/STAYC ; https://www.highup-ent.com/en/stayc-kicks-off-second-world-tour-stay-tuned-in-seoul-this-april-tickets-sell-out-instantly/ ; https://www.koreatimes.co.kr/entertainment/k-pop/20250211/stayc-to-kick-off-world-tour-with-seoul-concert-in-april ; https://www.highup-ent.com/en/%EC%8A%A4%ED%85%8C%EC%9D%B4%EC%94%A8-%EB%8D%B0%EB%B7%94-%EC%B2%AB-%ED%8C%AC%EB%AF%B8%ED%8C%85-stay-cool-party-%EC%84%B1%EB%A3%8C-%EC%82%AC%EB%9E%91-%EB%8A%90%EA%BC%88/ ; https://en.wikipedia.org/wiki/Teddy_Bear_(STAYC_song) ; https://en.wikipedia.org/wiki/Metamorphic_(album) ; https://www.highup-ent.com/en/stayc/ ; https://www.nme.com/features/music-interviews/stayc-interview-meteoric-rise-run2u-viral-hit-catchphrase-identity-future-sound-3191926. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('Apink True or False', 'Ten true or false statements on Apink: the debut EP, hits like Mr. Chu, LUV and Dumhdurum, Japanese singles and the duo Apink Chobom.', 41, 'true_false', 'easy', 'true_false', '[{"question":"Apink''s debut EP, released in 2011, was titled Seven Springs of Apink.","correct":true,"fun_fact":"It came out on April 19, 2011, led by Mollayo, or I Don''t Know, and Lee Gi-kwang of Beast appears in its music video.","source":"https://en.wikipedia.org/wiki/Apink"},{"question":"NoNoNo was the title track of Une Année, Apink''s first studio album.","correct":false,"fun_fact":"Une Année arrived in May 2012 with Hush as its title song. NoNoNo came out in July 2013 as the lead single of the EP Secret Garden.","source":"https://en.wikipedia.org/wiki/Apink"},{"question":"Apink''s 2014 hit Mr. Chu was composed by Duble Sidekick.","correct":true,"fun_fact":"Digipedi directed its tennis-themed video, and Gaon''s year-end chart placed it eighth among the best-selling digital songs of 2014.","source":"https://en.wikipedia.org/wiki/Mr._Chu"},{"question":"Pink LUV, Apink''s fifth EP, debuted at No. 1 on the Gaon Album Chart.","correct":true,"fun_fact":"Shinsadong Tiger composed the title song LUV, which earned Apink triple crowns on The Show, Show! Music Core and Inkigayo.","source":"https://en.wikipedia.org/wiki/Pink_Luv"},{"question":"Apink''s first Japanese single, released in October 2014, was a Japanese version of Mr. Chu.","correct":false,"fun_fact":"Their Japanese debut single was NoNoNo, which reached No. 4 on Oricon''s weekly chart. A Japanese Mr. Chu followed in February 2015.","source":"https://en.wikipedia.org/wiki/Apink"},{"question":"Apink''s 2016 Japanese song Brand New Days was used as the opening theme of an anime series.","correct":true,"fun_fact":"The series was Rilu Rilu Fairilu, and the group released the song''s music video on February 25, 2016.","source":"https://en.wikipedia.org/wiki/Apink"},{"question":"Apink held their first headlining concert, Pink Paradise, at Jamsil Indoor Stadium.","correct":false,"fun_fact":"Pink Paradise took place at Olympic Hall on January 30 and 31, 2015, and its 7,200 tickets went in two minutes. Jamsil hosted their second concert.","source":"https://en.wikipedia.org/wiki/Apink"},{"question":"Dumhdurum, the 2020 lead single of the EP Look, reached No. 1 on the Gaon Digital Chart.","correct":false,"fun_fact":"It entered at No. 4 and peaked at No. 2, and in its second week of promotion Apink won on all six weekly music shows.","source":"https://en.wikipedia.org/wiki/Look_(EP)"},{"question":"Apink Chobom, the duo of Chorong and Bomi, debuted in July 2022 with the single album Dilemma.","correct":false,"fun_fact":"Their debut single album was Copycat, a nu-disco track. The two began preparing it once Apink had wrapped up promotions for Dilemma.","source":"https://en.wikipedia.org/wiki/Copycat_(Apink_Chobom_song)"},{"question":"Apink marked their first anniversary with a song named after the date of their debut.","correct":true,"fun_fact":"Leader Park Cho-rong wrote its lyrics and Kim Jin-hwan composed it. Later anniversary songs include Promise U, The Wave and Thank You.","source":"https://en.wikipedia.org/wiki/Apink"}]'::jsonb, '2026-12-13'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Apink ; https://en.wikipedia.org/wiki/Mr._Chu ; https://en.wikipedia.org/wiki/Pink_Luv ; https://en.wikipedia.org/wiki/Look_(EP) ; https://en.wikipedia.org/wiki/Copycat_(Apink_Chobom_song) ; https://en.wikipedia.org/wiki/Seven_Springs_of_Apink ; https://en.wikipedia.org/wiki/Secret_Garden_(Apink_EP) ; https://en.wikipedia.org/wiki/Une_Ann%C3%A9e ; https://en.wikipedia.org/wiki/Apink_discography ; https://www.wikidata.org/wiki/Q483286. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('NCT 127: The Sticker Era', 'Ten questions on NCT 127''s 2021 album Sticker: the lead single, its video, chart and sales numbers, the repackage and the world tour.', 34, 'multiple_choice', 'medium', 'era', '[{"question":"Which instrument stands out in the sound of NCT 127''s 2021 single Sticker?","options":["Violin","Flute","Saxophone","Harmonica"],"correct":1,"fun_fact":"Its co-composer Dem Jointz had worked on three earlier NCT 127 singles: Cherry Bomb, Kick It and Punch.","source":"https://en.wikipedia.org/wiki/Sticker_(song)"},{"question":"Which two NCT 127 members co-wrote the lyrics of Sticker with Yoo Young-jin?","options":["Haechan and Jungwoo","Doyoung and Jaehyun","Johnny and Yuta","Taeyong and Mark"],"correct":3,"fun_fact":"Yoo Young-jin urged the group''s two rappers to write their own verses so the track would sound like NCT.","source":"https://en.wikipedia.org/wiki/Sticker_(song)"},{"question":"What concept does the music video for Sticker follow?","options":["A haunted boarding school","An underwater city","A medieval royal court","A futuristic space cowboy world"],"correct":3,"fun_fact":"Its neon-lit sets mix CGI with video game touches, a look NME compared to Las Vegas.","source":"https://en.wikipedia.org/wiki/Sticker_(song)"},{"question":"In 2021, the single Sticker gave NCT 127 their first entry on which Billboard chart?","options":["Billboard 200","Billboard Global 200","Billboard Hot 100","World Digital Song Sales"],"correct":1,"fun_fact":"It peaked at No. 101 there, and it also opened at No. 5 on World Digital Song Sales, the group''s eleventh top-five entry on that list.","source":"https://en.wikipedia.org/wiki/Sticker_(song)"},{"question":"By its release day in September 2021, roughly how many pre-orders had Sticker gathered?","options":["900,000","1.5 million","2.2 million","3.5 million"],"correct":2,"fun_fact":"That was more than four times the group''s previous best of about 530,000 pre-orders, set by Neo Zone.","source":"https://en.wikipedia.org/wiki/Sticker_(album)"},{"question":"Which single led the October 2021 repackage of Sticker?","options":["Ay-Yo","Lemonade","Breakfast","Favorite (Vampire)"],"correct":3,"fun_fact":"Kenzie, Darkchild and Rodnae Chikk Bell wrote it, and in November 2021 it won twice on M Countdown and once on Show! Music Core.","source":"https://en.wikipedia.org/wiki/Favorite_(Vampire)"},{"question":"What was the name of the tour NCT 127 launched in December 2021 in support of Sticker?","options":["Neo City: The Origin","Neo City: The Unity","Neo City: The Link","Neo City: The Momentum"],"correct":2,"fun_fact":"Running until January 2023, the tour played 28 shows in 17 cities and drew more than 700,000 spectators.","source":"https://en.wikipedia.org/wiki/Neo_City_%E2%80%93_The_Link"},{"question":"Which Seoul venue hosted the December 2021 opening shows of NCT 127''s tour for Sticker?","options":["Gocheok Sky Dome","Jamsil Indoor Stadium","KSPO Dome","Seoul World Cup Stadium"],"correct":0,"fun_fact":"Under COVID-19 rules only 5,000 fans were let in and shouting was banned, so the crowd cheered by clapping.","source":"https://en.wikipedia.org/wiki/Neo_City_%E2%80%93_The_Link"},{"question":"Sticker, released on September 17, 2021, is which of NCT 127''s Korean-language studio albums?","options":["Their first","Their second","Their third","Their fourth"],"correct":2,"fun_fact":"It followed the Korean albums Regular-Irregular and Neo Zone (March 2020), and the Japanese EP Loveholic had come out earlier in 2021, in February.","source":"https://en.wikipedia.org/wiki/Sticker_(album)"},{"question":"On which American talk show did NCT 127 perform Sticker when the album came out in September 2021?","options":["The Late Late Show with James Corden","The Late Show with Stephen Colbert","The Tonight Show Starring Jimmy Fallon","Jimmy Kimmel Live!"],"correct":0,"fun_fact":"Before release, a teaser called Who Is Sticker cast the members as engineering students by day and computer hackers by night.","source":"https://en.wikipedia.org/wiki/Sticker_(album)"}]'::jsonb, '2026-12-14'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Sticker_(song) ; https://en.wikipedia.org/wiki/Sticker_(album) ; https://en.wikipedia.org/wiki/Favorite_(Vampire) ; https://en.wikipedia.org/wiki/Neo_City_%E2%80%93_The_Link ; https://en.wikipedia.org/wiki/NCT_127 ; https://en.wikipedia.org/wiki/NCT_127_discography. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('Korea''s Year-End Chart Toppers', 'Ten years of South Korea''s biggest hits: name the song or artist that ended each year at No. 1 on the Gaon, now Circle, Digital Chart.', null, 'multiple_choice', 'hard', 'knowledge', '[{"question":"Which song finished first on the Gaon Digital Chart''s year-end ranking for 2011?","options":["Lonely","Roly-Poly","Pinocchio (Danger)","Tonight"],"correct":1,"fun_fact":"T-ara''s song never reached No. 1 on a weekly or monthly Gaon chart that year, yet it still led the full-year ranking.","source":"https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2011"},{"question":"Which song topped the Gaon Digital Chart''s year-end list for 2013?","options":["Gentleman","Bom Bom Bom","Gone Not Around Any Longer","What''s Your Name?"],"correct":0,"fun_fact":"Psy''s single held the weekly top spot for two weeks in April 2013 and was also the best performer of that month.","source":"https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2013"},{"question":"Which song ranked No. 1 on the Gaon Digital Chart''s year-end list for 2014?","options":["Eyes, Nose, Lips","Some","Wild Flower","A Midsummer Night''s Sweetness"],"correct":1,"fun_fact":"The duet by Soyou and Junggigo spent two weeks at No. 1 in February 2014 and was that month''s top song as well.","source":"https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2014"},{"question":"Which BIGBANG single was the Gaon Digital Chart''s best-performing song of 2015?","options":["Loser","Bae Bae","Bang Bang Bang","Sober"],"correct":2,"fun_fact":"G-Dragon wrote and composed it with Teddy Park, and Gaon counted 1,581,284 downloads of it over the year.","source":"https://en.wikipedia.org/wiki/Bang_Bang_Bang_(BigBang_song)"},{"question":"Which singer had the Gaon Digital Chart''s best-performing song of 2017?","options":["Ailee","IU","Crush","Heize"],"correct":0,"fun_fact":"Her song for the drama Guardian: The Lonely and Great God, composed by the duo Rocoberry, led Gaon''s yearly digital, download and streaming charts.","source":"https://en.wikipedia.org/wiki/I_Will_Go_to_You_Like_the_First_Snow"},{"question":"Which song was the Gaon Digital Chart''s best-performing single of 2019?","options":["The Day Was Beautiful","Four Seasons","2002","Boy with Luv"],"correct":2,"fun_fact":"Sung by English singer Anne-Marie, it was the first foreign song to end a year at the top of the chart, and it also led the June 2019 monthly chart.","source":"https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2019"},{"question":"Which artist had the Gaon Digital Chart''s best-performing song of 2020?","options":["Changmo","Jo Jung-suk","Zico","Jang Beom-june"],"correct":2,"fun_fact":"His single Any Song spent seven weeks at No. 1 on the weekly chart in 2020, and Changmo''s Meteor came second for the year.","source":"https://en.wikipedia.org/wiki/Circle_Digital_Chart"},{"question":"Which song was the Gaon Digital Chart''s year-end No. 1 for 2021?","options":["Rollin''","Celebrity","Dynamite","Next Level"],"correct":1,"fun_fact":"IU''s single held No. 1 for six weeks from late January 2021, and she spent twelve weeks on top that year with four different songs.","source":"https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2021"},{"question":"Which song topped the Circle Digital Chart''s year-end list for 2022?","options":["Tomboy","Eleven","Still Life","Love Dive"],"correct":3,"fun_fact":"IVE''s song held No. 1 for four weeks in a row, a run the group matched later that year with After Like.","source":"https://en.wikipedia.org/wiki/List_of_Circle_Digital_Chart_number_ones_of_2022"},{"question":"Which song was the Circle Digital Chart''s year-end No. 1 for 2025?","options":["APT.","Whiplash","Home Sweet Home","Drowning"],"correct":3,"fun_fact":"Woodz first released it on his 2023 EP OO-LI, and it reached No. 1 on the weekly chart in May 2025, more than two years later.","source":"https://en.wikipedia.org/wiki/Woodz"}]'::jsonb, '2026-12-15'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2011 ; https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2013 ; https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2014 ; https://en.wikipedia.org/wiki/Bang_Bang_Bang_(BigBang_song) ; https://en.wikipedia.org/wiki/I_Will_Go_to_You_Like_the_First_Snow ; https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2019 ; https://en.wikipedia.org/wiki/Circle_Digital_Chart ; https://en.wikipedia.org/wiki/List_of_Gaon_Digital_Chart_number_ones_of_2021 ; https://en.wikipedia.org/wiki/List_of_Circle_Digital_Chart_number_ones_of_2022 ; https://en.wikipedia.org/wiki/Woodz ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2011&hitYear=2011&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2013&hitYear=2013&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2014&hitYear=2014&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2015&hitYear=2015&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2017&hitYear=2017&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2019&hitYear=2019&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2020&hitYear=2020&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2021&hitYear=2021&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2022&hitYear=2022&termGbn=year&yearTime=3 ; https://circlechart.kr/page_chart/onoff.circle?nationGbn=T&serviceGbn=ALL&targetTime=2025&hitYear=2025&termGbn=year&yearTime=3. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('NCT DREAM: From Chewing Gum to Smoothie', 'Ten easy questions on NCT DREAM: the label, the first win, the old graduation rule, singles from Ridin'' to Smoothie and the members.', 35, 'multiple_choice', 'easy', 'group_specific', '[{"question":"Which agency formed NCT DREAM as a unit of NCT?","options":["SM Entertainment","JYP Entertainment","YG Entertainment","HYBE"],"correct":0,"fun_fact":"NCT DREAM was the third NCT sub-unit to debut, after NCT U and NCT 127.","source":"https://en.wikipedia.org/wiki/NCT_Dream"},{"question":"With which song did NCT DREAM win their first music show trophy, in February 2017?","options":["Chewing Gum","Go","We Young","My First and Last"],"correct":3,"fun_fact":"The win came on February 14, 2017, on the 100th episode of The Show, and the song led their single album The First.","source":"https://en.wikipedia.org/wiki/NCT_Dream"},{"question":"In which year did SM end NCT DREAM''s graduation system?","options":["2018","2019","2020","2021"],"correct":2,"fun_fact":"Mark, who had left under the old rule on December 31, 2018, rejoined the unit once the change took effect.","source":"https://en.wikipedia.org/wiki/NCT_Dream"},{"question":"Which EP was announced as Mark''s last comeback with NCT DREAM before his graduation?","options":["We Young","We Go Up","We Boom","Reload"],"correct":1,"fun_fact":"Released in September 2018, it included a Mandarin version of its title song and became the unit''s second No. 1 on the Gaon Album Chart.","source":"https://en.wikipedia.org/wiki/We_Go_Up_(NCT_Dream_EP)"},{"question":"Ridin'' was the lead single of which 2020 NCT DREAM EP?","options":["We Boom","Beatbox","Hello Future","Reload"],"correct":3,"fun_fact":"Recorded by the six members of the time, the five-track EP took the group to No. 1 on Billboard''s Emerging Artists chart for the first time.","source":"https://en.wikipedia.org/wiki/Reload_(EP)"},{"question":"In the 2024 video for Smoothie, NCT DREAM play a real-life version of which mobile game?","options":["Fruit Ninja","Angry Birds","Temple Run","Subway Surfers"],"correct":0,"fun_fact":"Smoothie led the EP Dream()scape, a title pronounced dream escape, released on March 25, 2024.","source":"https://en.wikipedia.org/wiki/Dream%28%29scape"},{"question":"In April 2022, Glitch Mode became NCT DREAM''s first entry on which US chart?","options":["Billboard Heatseekers Albums","Billboard 200","Billboard World Albums","Billboard Hot 100"],"correct":1,"fun_fact":"The second studio album entered at No. 50, and at home it opened at No. 1 on the monthly Gaon chart with 1,646,949 copies sold.","source":"https://en.wikipedia.org/wiki/Glitch_Mode"},{"question":"Which of these idols is a member of NCT DREAM?","options":["Johnny","Renjun","Doyoung","Yuta"],"correct":1,"fun_fact":"Renjun was one of the five new faces who joined Mark and Haechan when SM announced NCT DREAM in August 2016.","source":"https://en.wikipedia.org/wiki/NCT_Dream"},{"question":"Which NCT DREAM member teamed up with Jeno in NCT JNJM, the NCT unit formed in 2026?","options":["Jaemin","Chenle","Jisung","Haechan"],"correct":0,"fun_fact":"NCT JNJM became NCT''s seventh sub-unit and released its first EP, Both Sides, on February 23, 2026.","source":"https://en.wikipedia.org/wiki/NCT_JNJM"},{"question":"NCT DREAM sang Trigger the Fever as the official song of which 2017 tournament in South Korea?","options":["Asian Games","Winter Universiade","FIFA U-20 World Cup","AFC Asian Cup"],"correct":2,"fun_fact":"The unit served as the tournament''s official ambassadors and sang the song at its opening ceremony.","source":"https://en.wikipedia.org/wiki/NCT_Dream"}]'::jsonb, '2026-12-16'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/NCT_Dream ; https://en.wikipedia.org/wiki/We_Go_Up_(NCT_Dream_EP) ; https://en.wikipedia.org/wiki/Reload_(EP) ; https://en.wikipedia.org/wiki/Dream%28%29scape ; https://en.wikipedia.org/wiki/Glitch_Mode ; https://en.wikipedia.org/wiki/NCT_(group) ; https://www.wikidata.org/wiki/Q47002841 ; https://www.smentertainment.com/en/artist/ ; https://en.wikipedia.org/wiki/NCT_JNJM. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop Songs With Foreign Titles', 'Ten K-pop songs with titles in Spanish, French, Italian, Japanese and more: match each one to the artist or album behind it.', null, 'multiple_choice', 'medium', 'fun', '[{"question":"Which group released Hola Hola as the title track of its 2017 debut EP?","options":["Pentagon","Golden Child","The Boyz","KARD"],"correct":3,"fun_fact":"The music video shows the members traveling through Los Angeles, Las Vegas, Mexico and Brazil.","source":"https://en.wikipedia.org/wiki/Hola_Hola_(Kard_song)"},{"question":"Which girl group released the single Adios in August 2019?","options":["EVERGLOW","Weki Meki","Cherry Bullet","Rocket Punch"],"correct":0,"fun_fact":"It led the single album Hush. On Billboard''s World Digital Song Sales it got as high as No. 2 and charted for six weeks in all.","source":"https://en.wikipedia.org/wiki/Everglow"},{"question":"Senorita (2019) was the title track of which (G)I-DLE EP?","options":["I Am","I Made","I Trust","I Burn"],"correct":1,"fun_fact":"Soyeon wrote the lyrics and produced it with Big Sancho, using castanets and brass to give it a flamenco flavor.","source":"https://en.wikipedia.org/wiki/Senorita_((G)I-dle_song)"},{"question":"Mamacita (2014) led the seventh Korean studio album of which boy group?","options":["2PM","TVXQ","Shinhwa","Super Junior"],"correct":3,"fun_fact":"Teddy Riley co-composed it, and the western-themed video casts the members as a sheriff, a matador and a robber, among others.","source":"https://en.wikipedia.org/wiki/Mamacita_(Super_Junior_song)"},{"question":"Which girl group released Mamma Mia in August 2014, its first release with Heo Youngji?","options":["After School","Rainbow","Secret","KARA"],"correct":3,"fun_fact":"Duble Sidekick composed the song, which led the EP Day & Night. Heo Youngji had won her spot on the TV show Kara Project.","source":"https://en.wikipedia.org/wiki/Day_%26_Night_(Kara_EP)"},{"question":"Bon Voyage, released in September 2020, marked the solo debut of which Oh My Girl member?","options":["YooA","Arin","Hyojung","Seunghee"],"correct":0,"fun_fact":"It was a five-song EP from WM Entertainment, led by a title track of the same name.","source":"https://en.wikipedia.org/wiki/Bon_Voyage_(EP)"},{"question":"Coup d''Etat (2013) was the title track of which rapper''s second studio album?","options":["Zico","T.O.P","G-Dragon","Jay Park"],"correct":2,"fun_fact":"American DJs Diplo and Baauer feature on it as co-producers, and it samples Gil Scott-Heron''s The Revolution Will Not Be Televised.","source":"https://en.wikipedia.org/wiki/Coup_d%27Etat_(song)"},{"question":"Which group''s 2022 single Maison takes its title from the French word for home?","options":["Dreamcatcher","Weeekly","Billlie","Purple Kiss"],"correct":0,"fun_fact":"A coded teaser hid the title before release, and the song pleads for the Earth to be saved from global warming and pollution.","source":"https://en.wikipedia.org/wiki/Apocalypse:_Save_Us"},{"question":"Suki to Iwasetai, a Japanese title meaning Tell Me You Love Me, was the 2019 Japanese debut single of which group?","options":["Kep1er","IZ*ONE","TWICE","NiziU"],"correct":1,"fun_fact":"Yasushi Akimoto produced it and wrote its lyrics, and it entered Oricon''s weekly singles chart at No. 2 with 221,640 copies sold.","source":"https://en.wikipedia.org/wiki/Suki_to_Iwasetai"},{"question":"Luna, a 2021 lead single that sets gayageum strings over trap beats, is by which boy group?","options":["CIX","VERIVERY","ONEUS","Cravity"],"correct":2,"fun_fact":"It led the EP Blood Moon and brought the group its first music show win, on Show Champion on November 17, 2021.","source":"https://en.wikipedia.org/wiki/Blood_Moon_(EP)"}]'::jsonb, '2026-12-17'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Hola_Hola_(Kard_song) ; https://en.wikipedia.org/wiki/Everglow ; https://en.wikipedia.org/wiki/Senorita_((G)I-dle_song) ; https://en.wikipedia.org/wiki/Mamacita_(Super_Junior_song) ; https://en.wikipedia.org/wiki/Day_%26_Night_(Kara_EP) ; https://en.wikipedia.org/wiki/Bon_Voyage_(EP) ; https://en.wikipedia.org/wiki/Coup_d%27Etat_(song) ; https://en.wikipedia.org/wiki/Apocalypse:_Save_Us ; https://en.wikipedia.org/wiki/Suki_to_Iwasetai ; https://en.wikipedia.org/wiki/Blood_Moon_(EP) ; https://en.wikipedia.org/wiki/Kard_(group) ; https://en.wikipedia.org/wiki/Oh_My_Girl ; https://en.wikipedia.org/wiki/I-dle_discography ; https://en.wikipedia.org/wiki/Oneus. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('2NE1: The Crush Era', 'Hard questions on 2NE1''s 2014 Crush era: Come Back Home, Gotta Be You, MTBD, the album''s acclaim and the All or Nothing World Tour.', 33, 'multiple_choice', 'hard', 'era', '[{"question":"Come Back Home takes its title from a 1995 song by which group, as a tribute?","options":["H.O.T.","Deux","Seo Taiji and Boys","Sechs Kies"],"correct":2,"fun_fact":"YG founder Yang Hyun-suk was a member of that group. CL confirmed the nod in an interview, while saying the video would go in a different direction.","source":"https://en.wikipedia.org/wiki/Come_Back_Home_(2NE1_song)"},{"question":"In its first week, Come Back Home placed No. 2 on the Gaon Digital Chart behind which Girls'' Generation single?","options":["Mr.Mr.","I Got a Boy","Lion Heart","Catch Me If You Can"],"correct":0,"fun_fact":"A week later it climbed to the top and stayed there for two weeks, the ninth and last No. 1 that 2NE1 scored on that chart.","source":"https://en.wikipedia.org/wiki/Come_Back_Home_(2NE1_song)"},{"question":"The Come Back Home video, set in a near-future city with a virtual paradise, was compared to which 1999 film?","options":["The Matrix","Fight Club","Being John Malkovich","eXistenZ"],"correct":0,"fun_fact":"Dee Shin directed the clip, whose production cost was put at about half a million dollars.","source":"https://en.wikipedia.org/wiki/Come_Back_Home_(2NE1_song)"},{"question":"Which track on Crush is a solo song by the group''s leader, CL?","options":["If I Were You","Happy","MTBD","Baby I Miss You"],"correct":2,"fun_fact":"Its Korean title, Menbung, translates as Mental Breakdown, and in 2017 Billboard ranked it No. 2 on its list of the best K-pop deep cuts of the decade so far.","source":"https://en.wikipedia.org/wiki/Crush_(2NE1_album)"},{"question":"The pop art look of the Gotta Be You video mixes Roy Lichtenstein''s comics with which artist''s Brillo Boxes?","options":["Keith Haring","Andy Warhol","Jeff Koons","Takashi Murakami"],"correct":1,"fun_fact":"Designer Jeremy Scott worked with the group on the video, which came out in May 2014 to celebrate five years since their debut.","source":"https://en.wikipedia.org/wiki/Gotta_Be_You_(2NE1_song)"},{"question":"Where did Crush land on Billboard''s list of the 10 best K-pop albums of 2014?","options":["No. 1","No. 2","No. 5","No. 10"],"correct":0,"fun_fact":"Rolling Stone also put it sixth among the best pop albums of 2014, the only record by an Asian artist on that list.","source":"https://en.wikipedia.org/wiki/Crush_(2NE1_album)"},{"question":"Crush includes a Korean version of which song that 2NE1 first released as a Japanese single in 2012?","options":["Go Away","Ugly","Lonely","Scream"],"correct":3,"fun_fact":"YG moved the album''s digital release from February 24 to February 27, 2014, so that it would line up with CL''s birthday.","source":"https://en.wikipedia.org/wiki/Crush_(2NE1_album)"},{"question":"Which YG boy group were special guests on the All or Nothing World Tour from Seoul to Jakarta?","options":["iKON","Winner","Big Bang","Epik High"],"correct":1,"fun_fact":"The tour began at the SK Olympic Handball Gymnasium in Seoul on March 1, 2014, and grew to 20 concerts across Asia.","source":"https://en.wikipedia.org/wiki/All_or_Nothing_World_Tour"},{"question":"After the All or Nothing World Tour, 2NE1''s next tour came with their 2024 reunion. What was it called?","options":["Nolza Tour","New Evolution Global Tour","Born Pink World Tour","Welcome Back Tour"],"correct":3,"fun_fact":"YG revealed the reunion in July 2024 to mark the group''s 15th anniversary, and the tour opened at Seoul''s Olympic Hall that October.","source":"https://en.wikipedia.org/wiki/2NE1"},{"question":"At the 2014 Melon Music Awards, Come Back Home won the award for which genre?","options":["Rock","Electronic","Ballad","Rap/Hip Hop"],"correct":1,"fun_fact":"It was also named Song of the Year for March at the Gaon Chart K-pop Awards, and it won three music show trophies in March 2014.","source":"https://en.wikipedia.org/wiki/Come_Back_Home_(2NE1_song)"}]'::jsonb, '2026-12-18'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Come_Back_Home_(2NE1_song) ; https://en.wikipedia.org/wiki/Crush_(2NE1_album) ; https://en.wikipedia.org/wiki/Gotta_Be_You_(2NE1_song) ; https://en.wikipedia.org/wiki/All_or_Nothing_World_Tour ; https://en.wikipedia.org/wiki/2NE1 ; https://en.wikipedia.org/wiki/2014_Melon_Music_Awards ; https://www.nme.com/news/music/yg-announces-2ne1-will-return-with-a-world-tour-3776672 ; https://www.billboard.com/music/music-news/kpop-deep-cuts-best-8054669/. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop and Korean Tradition True or False', 'True or false on Korean tradition in K-pop: hanbok in videos and on stage, gugak instruments, Daechwita and songs that borrow from the past.', null, 'true_false', 'medium', 'true_false', '[{"question":"BLACKPINK dance in modified hanbok in their 2020 video for How You Like That.","correct":true,"fun_fact":"The Korea Times reported that Rosé''s outfit drew on the cheollik, a garment of military officials, and the group also wore hanbok on The Tonight Show.","source":"https://www.koreatimes.co.kr/entertainment/20200709/hanbok-sweeps-global-k-pop-fans-off-their-feet"},{"question":"Haegeum, a 2023 single by Agust D, takes its name from a traditional Korean drum.","correct":false,"fun_fact":"A haegeum is a two-stringed fiddle, and the song uses one in its arrangement. The title also works as wordplay on liberation, a theme of the track.","source":"https://en.wikipedia.org/wiki/Haegeum_(song)"},{"question":"Seo Taiji and Boys'' 1993 hit Anyhow Song (Hayeoga) features the taepyeongso, a traditional Korean instrument.","correct":true,"fun_fact":"Kim Duk-soo is credited with the taepyeongso and samul nori parts, and the album Seo Taiji and Boys II sold over 2.2 million copies.","source":"https://en.wikipedia.org/wiki/Seo_Taiji_and_Boys_II"},{"question":"VIXX''s 2017 single Shangri-La pairs synths with melodies inspired by Japanese enka.","correct":false,"fun_fact":"Its melodies take their cue from gugak, traditional Korean music, and the visuals of the release put Korean tradition front and center.","source":"https://www.koreatimes.co.kr/entertainment/k-pop/20250930/gugak-meets-k-pop-tracks-that-fuse-tradition-with-global-pop-sounds"},{"question":"The video for Agust D''s Daechwita is based on the 2005 film The King and the Clown.","correct":false,"fun_fact":"It draws on the 2012 film Masquerade instead, and Agust D plays both a king and the double who takes his place.","source":"https://en.wikipedia.org/wiki/Daechwita_(song)"},{"question":"NewJeans performed in hanbok at Gyeongbok Palace in Seoul in May 2024.","correct":true,"fun_fact":"The show was 2024 Korea On Stage, co-hosted by the Korea Heritage Service and KBS, and a filmed clip showed them singing Cool With You at Geunjeongjeon Hall.","source":"https://www.koreatimes.co.kr/amp/entertainment/k-pop/20240522/newjeans-wows-crowd-at-2024-korea-on-stage-at-gyeongbok-palace-in-hanbok-clothing"},{"question":"Agust D''s 2020 song Daechwita samples the traditional Korean military music it is named after.","correct":true,"fun_fact":"He has said the idea of using a real daechwita grew into pansori-style storytelling and kkwaenggwari percussion on the track.","source":"https://en.wikipedia.org/wiki/Daechwita_(song)"},{"question":"Billboard described Sunmi''s 2019 single Lalalay as Eurodance blended with traditional Korean sounds.","correct":false,"fun_fact":"Billboard heard Latin pop and dancehall in it, plus the taepyeongso, a traditional Korean horn. Sunmi shares the production credit with Frants.","source":"https://en.wikipedia.org/wiki/Lalalay"},{"question":"On Mnet''s Queendom in 2019, Oh My Girl covered Lovelyz''s Destiny in an arrangement featuring the gayageum.","correct":true,"fun_fact":"According to The Korea Times, the choreography of that stage was also styled after the graceful look of traditional Korean art.","source":"https://www.koreatimes.co.kr/entertainment/k-pop/20250930/gugak-meets-k-pop-tracks-that-fuse-tradition-with-global-pop-sounds"},{"question":"In her 2021 video for Lalisa, BLACKPINK''s Lisa sits on a throne in an outfit modeled on Korean royal court dress.","correct":false,"fun_fact":"That look is Thai instead, with a rad klao yod, a pointed headdress mostly seen in Thai traditional dance, and Phanom Rung Historical Park also features in the clip.","source":"https://en.wikipedia.org/wiki/Lalisa_(song)"}]'::jsonb, '2026-12-19'::date, 'verified', now(), 'Sources: https://www.koreatimes.co.kr/entertainment/20200709/hanbok-sweeps-global-k-pop-fans-off-their-feet ; https://en.wikipedia.org/wiki/Haegeum_(song) ; https://en.wikipedia.org/wiki/Seo_Taiji_and_Boys_II ; https://www.koreatimes.co.kr/entertainment/k-pop/20250930/gugak-meets-k-pop-tracks-that-fuse-tradition-with-global-pop-sounds ; https://en.wikipedia.org/wiki/Daechwita_(song) ; https://www.koreatimes.co.kr/amp/entertainment/k-pop/20240522/newjeans-wows-crowd-at-2024-korea-on-stage-at-gyeongbok-palace-in-hanbok-clothing ; https://en.wikipedia.org/wiki/Lalalay ; https://en.wikipedia.org/wiki/Lalisa_(song). Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('P1Harmony: From Siren to Sad Song', 'From their 2020 debut with Siren to Sad Song: P1Harmony''s name, fandom, leader, singles, a world tour and Billboard 200 entries.', 73, 'multiple_choice', 'medium', 'group_specific', '[{"question":"Siren was the lead single of P1Harmony''s October 2020 debut EP. What was that EP called?","options":["Disharmony: Break Out","Harmony: Zero In","Disharmony: Find Out","Disharmony: Stand Out"],"correct":3,"fun_fact":"All six members helped write the lyrics of its opening track, Intro; Breakthrough, and the EP reached No. 5 on the Gaon Album Chart.","source":"https://en.wikipedia.org/wiki/Disharmony:_Stand_Out"},{"question":"The name P1Harmony joins the word harmony with which two ideas?","options":["Plus and the number 1","Peace and the number 1","Power and first place","Planet and one world"],"correct":0,"fun_fact":"The members are meant to add up to one group with endless possibilities for harmonies, and the name is often shortened to P1H.","source":"https://en.wikipedia.org/wiki/P1Harmony"},{"question":"What is the official name of P1Harmony''s fandom?","options":["Harmonies","P1us","Melody","P1ece"],"correct":3,"fun_fact":"Revealed on April 20, 2021, the name says that fans are the pieces P1Harmony could not do without.","source":"https://en.wikipedia.org/wiki/P1Harmony"},{"question":"Which member is the leader of P1Harmony?","options":["Theo","Intak","Keeho","Jiung"],"correct":2,"fun_fact":"Keeho is also one of the group''s vocalists. The six members are Keeho, Theo, Jiung, Intak, Soul and Jongseob.","source":"https://en.wikipedia.org/wiki/P1Harmony"},{"question":"Which single led Disharmony: Break Out, the EP of P1Harmony''s first comeback in April 2021?","options":["Duh!","Do It Like This","Doom Du Doom","Scared"],"correct":3,"fun_fact":"The EP went on to be nominated for Album of the Year at the 2021 Mnet Asian Music Awards.","source":"https://en.wikipedia.org/wiki/P1Harmony"},{"question":"On which US talk show did P1Harmony make their American TV debut, performing Back Down in November 2022?","options":["Good Morning America","The Kelly Clarkson Show","The Late Late Show with James Corden","The Tonight Show Starring Jimmy Fallon"],"correct":1,"fun_fact":"The performance aired on November 29, one day before Back Down came out as the lead single of the EP Harmony: Set In.","source":"https://en.wikipedia.org/wiki/P1Harmony"},{"question":"Which EP, led by Jump, gave P1Harmony their first entry on the Billboard 200 in June 2023?","options":["Harmony: All In","Harmony: Set In","Harmony: Zero In","Disharmony: Find Out"],"correct":0,"fun_fact":"It entered at No. 51 and sold more than 250,000 copies, double their previous release, while the group placed No. 35 on the Artist 100.","source":"https://www.koreatimes.co.kr/entertainment/k-pop/20230622/p1harmony-enters-billboard-200-chart-for-first-time"},{"question":"With Killin'' It, P1Harmony won their first music show trophy in February 2024. On which show?","options":["Show Champion","Music Bank","The Show","M Countdown"],"correct":1,"fun_fact":"Killin'' It, released on February 5, 2024, was the group''s first full-length album and reached No. 39 on the Billboard 200.","source":"https://en.wikipedia.org/wiki/P1Harmony"},{"question":"Where did P1Harmony''s September 2024 EP Sad Song peak on the Billboard 200?","options":["No. 3","No. 16","No. 28","No. 60"],"correct":1,"fun_fact":"The EP tells a story of getting over loneliness through a superhero concept, and it reached No. 2 on the Circle Album Chart.","source":"https://en.wikipedia.org/wiki/Sad_Song_(EP)"},{"question":"How many cities did P1Harmony''s 2023 tour, P1ustage H: P1oneer, visit around the world?","options":["Twelve","Twenty","Thirty-nine","Fifty"],"correct":2,"fun_fact":"The tour opened on January 14, 2023, and FNC Entertainment counts 40 shows across those cities.","source":"https://en.wikipedia.org/wiki/P1Harmony"}]'::jsonb, '2026-12-20'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Disharmony:_Stand_Out ; https://en.wikipedia.org/wiki/P1Harmony ; https://en.wikipedia.org/wiki/Sad_Song_(EP) ; https://www.koreatimes.co.kr/entertainment/k-pop/20230622/p1harmony-enters-billboard-200-chart-for-first-time ; https://www.koreajoongangdaily.com/entertainment/your-playlist-p1harmony-members-finally-get-to-hear-fans-loud-and-clear-and-theyre-loving-it/10998543 ; https://www.nme.com/features/music-interviews/p1harmony-reflect-on-one-year-anniversary-new-album-3081632 ; https://fncent.com/P1Harmony/b/introduce/45597. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('Who Directed These K-pop Music Videos?', 'Ten famous K-pop music videos, from Gangnam Style to Ditto: name the director or production company behind each one.', null, 'multiple_choice', 'hard', 'knowledge', '[{"question":"Which production company made the 2017 video for the remix of BTS''s Mic Drop with Steve Aoki?","options":["Lumpens","Zanybros","GDW","Naive"],"correct":2,"fun_fact":"Woogie Kim of GDW directed it, and the mic drop at the end of the clip was inspired by Barack Obama''s at his last White House Correspondents'' Dinner.","source":"https://en.wikipedia.org/wiki/Mic_Drop_(song)"},{"question":"Which production team directed TWICE''s 2016 video for TT?","options":["Lumpens","Rigend Film","Digipedi","Naive"],"correct":3,"fun_fact":"Kim Young-jo and Yoo Seung-woo of the team had also made Like Ooh-Ahh and Cheer Up, and the TT video drew over 5 million YouTube views in under a day.","source":"https://en.wikipedia.org/wiki/TT_(song)"},{"question":"Who directed BIGBANG''s 2015 video for Bang Bang Bang?","options":["Seo Hyun-seung","Cho Soo-hyun","Hong Won-ki","Shin Hee-won"],"correct":0,"fun_fact":"Parris Goebel created the choreography, and she can be spotted in the clip herself.","source":"https://en.wikipedia.org/wiki/Bang_Bang_Bang_(BigBang_song)"},{"question":"Who directed the 2012 video for PSY''s Gangnam Style?","options":["Cho Soo-hyun","Hong Won-ki","Seo Hyun-seung","Shin Woo-seok"],"correct":0,"fun_fact":"The video was shot in Seoul over 48 hours in July 2012, and the same director went on to make the clip for PSY''s next single, Gentleman.","source":"https://en.wikipedia.org/wiki/Gangnam_Style_(music_video)"},{"question":"Which studio made LOONA''s 2019 video for Butterfly?","options":["Lumpens","Naive","GDW","Digipedi"],"correct":3,"fun_fact":"Digipedi stands for Digital Pedicure, and the studio was started by two art directors, Seong Won-mo and Park Sang-woo.","source":"https://en.wikipedia.org/wiki/Digipedi"},{"question":"Which production team directed (G)I-DLE''s 2020 video for Oh My God?","options":["Zanybros","Rigend Film","Digipedi","GDW"],"correct":1,"fun_fact":"Yoon Rima and Jang Dongju of Rigend Film directed it, and it became the group''s third video to pass 100 million views.","source":"https://en.wikipedia.org/wiki/Oh_My_God_((G)I-dle_song)"},{"question":"Who directed the two-part video for NewJeans''s Ditto in December 2022?","options":["Shin Woo-seok","Shin Hee-won","Seo Hyun-seung","Cho Soo-hyun"],"correct":0,"fun_fact":"He is an advertising director who heads Dolphiners Films, and part of the song''s lyrics came from Oohyo and The Black Skirts.","source":"https://en.wikipedia.org/wiki/Ditto_(song)"},{"question":"Which production company made Super Junior''s 2011 video for Mr. Simple?","options":["Naive","Lumpens","Zanybros","Rigend Film"],"correct":2,"fun_fact":"Director Hong Won-ki set it up in 2002 with cameraman Kim Jun-hong, and in 2020 it made the web series Goedam, which Netflix acquired.","source":"https://en.wikipedia.org/wiki/Zanybros"},{"question":"Which production company made ENHYPEN''s 2020 debut video, Given-Taken?","options":["Naive","Lumpens","Zanybros","GDW"],"correct":1,"fun_fact":"The company''s name began as a nickname a college professor gave its founder, taken from a German insult.","source":"https://en.wikipedia.org/wiki/Lumpens"},{"question":"Who directed Taeyeon''s 2016 video for 11:11?","options":["Shin Woo-seok","Hong Won-ki","Cho Soo-hyun","Shin Hee-won"],"correct":3,"fun_fact":"He works with ST-WT Productions, and in 2022 he also directed the video for Girls'' Generation''s Forever 1.","source":"https://en.wikipedia.org/wiki/Shin_Hee-won"}]'::jsonb, '2026-12-21'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Mic_Drop_(song) ; https://en.wikipedia.org/wiki/TT_(song) ; https://en.wikipedia.org/wiki/Bang_Bang_Bang_(BigBang_song) ; https://en.wikipedia.org/wiki/Gangnam_Style_(music_video) ; https://en.wikipedia.org/wiki/Digipedi ; https://en.wikipedia.org/wiki/Butterfly_(Loona_song) ; https://en.wikipedia.org/wiki/Oh_My_God_((G)I-dle_song) ; https://en.wikipedia.org/wiki/Ditto_(song) ; https://en.wikipedia.org/wiki/Zanybros ; https://en.wikipedia.org/wiki/Super_Junior_videography ; https://en.wikipedia.org/wiki/Lumpens ; https://en.wikipedia.org/wiki/Border:_Day_One ; https://en.wikipedia.org/wiki/Shin_Hee-won. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.'),
  ('K-pop Song Titles That Ask a Question', 'Easy questions on K-pop songs whose titles ask a question, from What Is Love? and Why Not? to What Do I Call You.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"Which girl group released What Is Love? in April 2018?","options":["TWICE","Red Velvet","GFriend","Momoland"],"correct":0,"fun_fact":"J.Y. Park wrote and composed the song, and it debuted at No. 1 on the Gaon Digital Chart.","source":"https://en.wikipedia.org/wiki/What_Is_Love%3F_(Twice_song)"},{"question":"Which girl group released Why Not? in October 2020?","options":["Dreamcatcher","Everglow","LOONA","Weki Meki"],"correct":2,"fun_fact":"It led their EP [12:00], and its video shows the members dancing on the surface of the Moon.","source":"https://en.wikipedia.org/wiki/Why_Not%3F_(song)"},{"question":"Which American rapper features on MONSTA X''s 2019 single Who Do U Love?","options":["French Montana","Wiz Khalifa","Pitbull","Lil Nas X"],"correct":0,"fun_fact":"It climbed to No. 26 on Billboard''s Mainstream Top 40 airplay chart, the group''s first single to enter it, and was up for Best K-pop at the 2019 MTV VMAs.","source":"https://en.wikipedia.org/wiki/Who_Do_U_Love%3F_(Monsta_X_song)"},{"question":"Which BIGBANG member released the solo single Who You? in September 2013?","options":["G-Dragon","Daesung","T.O.P","Taeyang"],"correct":0,"fun_fact":"It came out on September 2, 2013, the same day as Black, a single that features Jennie, then a YG trainee.","source":"https://en.wikipedia.org/wiki/Coup_d%27Etat_(G-Dragon_album)"},{"question":"Which girl group released What''s Your Name? in April 2013?","options":["Sistar","Rainbow","Secret","4Minute"],"correct":3,"fun_fact":"Produced by Brave Brothers, it reached No. 1 on the Gaon chart and is introduced on its EP by a short track called What''s My Name?","source":"https://en.wikipedia.org/wiki/Name_Is_4Minute"},{"question":"Which soloist released How''s This? in August 2016?","options":["Chung Ha","Sunmi","Jessi","Hyuna"],"correct":3,"fun_fact":"She co-wrote the hip-hop and trap track, and its club party video featured one hundred dancers.","source":"https://en.wikipedia.org/wiki/How%27s_This%3F"},{"question":"Which singer released What Do I Call You, her fourth Korean EP and its title track, in December 2020?","options":["IU","Sunmi","Taeyeon","BoA"],"correct":2,"fun_fact":"The physical edition of the EP also includes Happy, the digital single she had put out in May 2020.","source":"https://en.wikipedia.org/wiki/What_Do_I_Call_You"},{"question":"Who released the single What You Waiting For in July 2020?","options":["Chung Ha","Jeon Somi","Lee Hi","Jessi"],"correct":1,"fun_fact":"Teddy and R.Tee were among its producers, and in the video she plays several versions of herself, from timid to confident.","source":"https://en.wikipedia.org/wiki/What_You_Waiting_For_(Jeon_Somi_song)"},{"question":"Who released What Are You Up To as the lead single of his debut EP, Color on Me, in 2019?","options":["Ha Sung-woon","Kang Daniel","Kim Jae-hwan","Park Ji-hoon"],"correct":1,"fun_fact":"Music Bank handed him his first music show trophy as a solo artist for this song on August 9, 2019.","source":"https://en.wikipedia.org/wiki/What_Are_You_Up_To"},{"question":"Which singer made her solo debut with Why Don''t You Know, featuring rapper Nucksal, in June 2017?","options":["Sunmi","Jeon Somi","Chung Ha","Hyolyn"],"correct":2,"fun_fact":"The tropical house track is about a love that goes unanswered, and its video shows her dancing across a wide grassy field.","source":"https://en.wikipedia.org/wiki/Why_Don%27t_You_Know"}]'::jsonb, '2026-12-22'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/What_Is_Love%3F_(Twice_song) ; https://en.wikipedia.org/wiki/Why_Not%3F_(song) ; https://en.wikipedia.org/wiki/Who_Do_U_Love%3F_(Monsta_X_song) ; https://en.wikipedia.org/wiki/Coup_d%27Etat_(G-Dragon_album) ; https://en.wikipedia.org/wiki/Name_Is_4Minute ; https://en.wikipedia.org/wiki/How%27s_This%3F ; https://en.wikipedia.org/wiki/What_Do_I_Call_You ; https://en.wikipedia.org/wiki/What_You_Waiting_For_(Jeon_Somi_song) ; https://en.wikipedia.org/wiki/What_Are_You_Up_To ; https://en.wikipedia.org/wiki/Why_Don%27t_You_Know. Drafted with AI assistance, checked by Louis Pecchia on 2026-10-25.');

-- Check: every row this file just inserted (verified_at = now(), the start of this transaction) is a
-- kpop row (no site_id column yet, or site_id 'kpop'). If not, nothing is applied.
do $$
begin
  if exists (
    select 1 from public.quiz_bank qb
    where qb.verified_at = now() and qb.title in ('ITZY: From Debut to Born to Be', 'K-pop Idol MCs Through the Years', 'EXO: The XOXO Era', 'K-pop Songs With a Flower in the Title', 'GOT7 True or False', 'MAMAMOO: From Mr. Ambiguous to Starry Night', 'SHINee: The Odd Era of 2015', 'K-pop Songs of 2015', 'K-pop Songs on the Phone', 'STAYC: From So Bad to Cheeky Icy Thang', 'Apink True or False', 'NCT 127: The Sticker Era', 'Korea''s Year-End Chart Toppers', 'NCT DREAM: From Chewing Gum to Smoothie', 'K-pop Songs With Foreign Titles', '2NE1: The Crush Era', 'K-pop and Korean Tradition True or False', 'P1Harmony: From Siren to Sad Song', 'Who Directed These K-pop Music Videos?', 'K-pop Song Titles That Ask a Question') and not (coalesce(to_jsonb(qb) ->> 'site_id', 'kpop') = 'kpop')
  ) then
    raise exception 'daily bank lot 3: a row of this lot is not a kpop row, nothing applied';
  end if;
end $$;

-- Check: one kpop row per date, no clash with a row already scheduled on these dates.
select scheduled_date, count(*) from public.quiz_bank qb
where scheduled_date between '2026-12-03' and '2026-12-22' and status in ('verified', 'scheduled') and coalesce(to_jsonb(qb) ->> 'site_id', 'kpop') = 'kpop'
group by scheduled_date having count(*) > 1;

commit;
